import {prepareReviewLink} from './discovery-link.js';
import {ROUTES,createPath,validatePath,appendEvent,exportPath,importPath,serializePath,MAX_BYTES,kindLabel,eventSummary,discoverySummaryText,discoveryTextReport} from './discovery.mjs';
const $=id=>document.getElementById(id),KEY='reckoner-discovery-draft-v01';let path=null,recovery=null,epoch=0;
const tell=text=>{$('status').textContent=text;};
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function option(select,value,label){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}
for(const [id,route] of Object.entries(ROUTES))option($('goal'),id,route.label);
function advice(){const r=ROUTES[$('goal').value];$('advice').textContent=r.begin+' '+r.check;}$('goal').onchange=advice;advice();
function persist(){if(recovery!==null)return 'Original unreadable data is preserved. Start new search notes explicitly before replacing it.';try{sessionStorage.setItem(KEY,JSON.stringify(path));return '';}catch{return 'Tab storage unavailable. This work is kept in memory only; export your search notes to keep it.';}}
function draftInputs(){return JSON.stringify(['goal','title','by','actor','kind'].map(id=>[id,$(id).value]).concat([...$('fields').querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.value])));}
function field(id,label,type='text',choices=null){const wrap=document.createElement('label');wrap.textContent=label;const input=document.createElement(choices?'select':type==='textarea'?'textarea':'input');input.id='f-'+id;input.dataset.field=id;if(choices)for(const [value,text] of choices)option(input,value,text);else{if(type!=='textarea')input.type=type;input.maxLength=type==='textarea'?8000:2048;if(type==='textarea')input.rows=3;}wrap.append(input);$('fields').append(wrap);return input;}
function targets(kind,optional=false){return [...(optional?[['','No earlier search']]:[]),...(path?.events||[]).filter(e=>kind===null||e.kind===kind).map(e=>[e.id,eventSummary(e)])];}
function drawFields(){const k=$('kind').value;$('fields').replaceChildren();
 if(k==='clue'){field('text','Clue or memory','textarea');field('confidence','How do you know?',null,[['uncertain_memory','Uncertain memory'],['confident_memory','Confident memory'],['documented_clue','A documented clue (describe the source)']]);}
 if(k==='attempt'){field('query','Exact search query');field('destination','Search service or library');field('url','Public search URL','url');field('parentAttemptId','Earlier search this retries',null,targets('attempt',true));field('stage','Search stage',null,[['planned','Planned; not tried'],['reported_tried','I tried it (self-declared)']]);field('reason','Why this search or change?','textarea');}
 if(['outcome','candidate','complaint'].includes(k))field('attemptId','Search this concerns',null,targets('attempt'));
 if(k==='outcome'){field('result','What happened?',null,[['not_checked','Not checked'],['no_match_seen','No suitable match among results I inspected'],['too_many_results','Too many results'],['possible_match','Possible match'],['service_error','Service error'],['access_restricted','Access restricted']]);field('observed','What you actually observed','textarea');field('nextStep','Suggested next step (optional)','textarea');}
 if(k==='candidate'){field('url','Candidate source URL','url');field('locator','Page, passage or timestamp');field('match','Match assessment',null,[['possible','Possible; not confirmed'],['supported_by_passage','Supported by the passage I inspected'],['rejected','Rejected candidate']]);field('reason','Evidence and uncertainty','textarea');}
 if(k==='mentor'){field('targetId','Note your guidance concerns',null,targets(null));field('guidance','Explain a repeatable check','textarea');}
 if(k==='complaint'){field('expected','What you expected','textarea');field('actual','What happened','textarea');field('reproduction','Steps someone can repeat','textarea');field('workaround','Workaround, if any (optional)','textarea');}
}
function render(preserveDraft=false){if(!path)return;const draft=preserveDraft?[...$('fields').querySelectorAll('[data-field]')].map(input=>[input.dataset.field,input.value]):null;$('work').hidden=false;$('export').disabled=false;$('path-title').textContent=path.title;let summary=$('search-activity-summary');if(!summary){summary=document.createElement('p');summary.id='search-activity-summary';summary.setAttribute('role','status');summary.setAttribute('aria-live','polite');$('path-title').insertAdjacentElement('afterend',summary);}summary.textContent=discoverySummaryText(path);$('history').replaceChildren();for(const e of path.events){const li=document.createElement('li'),heading=document.createElement('strong'),details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');heading.textContent=kindLabel(e.kind)+(e.kind==='attempt'?' · '+({planned:'Planned; not tried',opening_requested:'Opening requested; results unchecked',reported_tried:'Tried; self-declared'}[e.stage]):'')+' · '+e.by+' · '+e.at;summary.textContent='View recorded details';pre.textContent=JSON.stringify(e,null,2);details.append(summary,pre);li.append(heading,details);if(e.kind==='attempt'){const a=document.createElement('a');const target=new URL(e.url);a.textContent='Open recorded search: '+target.href;a.href=target.href;a.target='_blank';a.rel='noopener noreferrer';a.addEventListener('click',()=>{try{path=appendEvent(path,{kind:'attempt',by:$('actor').value.trim()||path.createdBy,query:e.query,destination:e.destination,url:e.url,parentAttemptId:e.id,reason:'User requested this recorded search link.',stage:'opening_requested'});epoch++;const note=persist();render(true);tell('Opening requested; results and success remain unchecked. '+note);}catch(error){tell(error.message);}});li.append(document.createElement('br'),a);}if(e.kind==='candidate'&&e.match!=='rejected'){const button=document.createElement('button');button.type='button';button.textContent='Prepare a separate document review: '+new URL(e.url).href;button.onclick=async()=>{const original=path,ticket=epoch,inputs=draftInputs();button.disabled=true;try{const link=await prepareReviewLink({path:original,candidateId:e.id,isCurrent:()=>path===original&&epoch===ticket&&draftInputs()===inputs,storage:localStorage,baseUrl:location.href});const a=document.createElement('a');a.href=link.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent=link.label;const note=document.createElement('p');note.textContent=link.scope+' Click the link to open it. If your browser blocks a new tab, copy the link and open it manually. Your search notes stay here.';li.append(a,note);a.focus();tell('Separate review prepared. Click its link to open the new workspace. Your current review is unchanged. Export both records for backup.');}catch(error){tell(error.message);}finally{button.disabled=false;}};li.append(button);}$('history').append(li);}drawFields();if(draft)for(const [key,value] of draft){const input=[...$('fields').querySelectorAll('[data-field]')].find(n=>n.dataset.field===key);if(input)input.value=value;}}
$('kind').onchange=drawFields;
$('start').onsubmit=event=>{event.preventDefault();if((path||recovery!==null)&&!confirm('Start new search notes? Save your current notes or recovery data first to keep them.'))return;try{path=createPath({goal:$('goal').value,title:$('title').value.trim(),by:$('by').value.trim()});epoch++;recovery=null;$('recover').hidden=true;$('actor').value=path.createdBy;const note=persist();render();tell('Search notes started. Add a clue or search without guessing missing details. '+note);}catch(error){tell(error.message);}};
$('add').onsubmit=event=>{event.preventDefault();try{const fields={};for(const input of $('fields').querySelectorAll('[data-field]'))fields[input.dataset.field]=input.value;if(fields.parentAttemptId==='')fields.parentAttemptId=null;path=appendEvent(path,{kind:$('kind').value,by:$('actor').value.trim(),...fields});epoch++;const note=persist();render();tell((note?'Note recorded in this session. ':'Note saved in this tab. Export a file before closing the tab. ')+'Earlier notes remain intact. '+note);}catch(error){tell(error.message);}};
$('export').onclick=async()=>{try{if(!path)return;const packet=await exportPath(path);download('discovery-path.json',serializePath(packet));tell('Search notes exported with a change-detection digest, not a signature.');}catch(error){tell(error.message);}};
$('print').onclick=()=>window.print();const reportButton=document.createElement('button');reportButton.type='button';reportButton.id='export-search-report';reportButton.textContent='Save readable search notes';reportButton.onclick=()=>{try{if(!path)throw Error('Start or open search notes first.');download('search-notes.txt',discoveryTextReport(path),'text/plain;charset=utf-8');tell('Readable search notes saved. Keep the JSON file to reopen and check its digest.');}catch(error){tell(error.message);}};$('print').insertAdjacentElement('afterend',reportButton);
$('import').onchange=async event=>{const file=event.target.files[0];if(!file)return;const ticket=++epoch,original=path,inputs=draftInputs();try{if(file.size>MAX_BYTES)throw Error('Choose saved search notes under 2 MB.');const next=await importPath(await file.text());if(epoch!==ticket||path!==original||draftInputs()!==inputs)throw Error('The search notes changed while the file loaded. Open the saved notes again when ready.');if((path||recovery!==null)&&!confirm('Replace these search notes with the checked file? Export current work first to keep it.'))return;path=next;epoch++;recovery=null;$('recover').hidden=true;$('goal').value=path.goal;advice();$('actor').value=path.createdBy;const note=persist();render();tell('Digest checked. Contributor identity and observations remain unverified. '+note);}catch(error){tell(error.message);}finally{event.target.value='';}};
$('recover').onclick=()=>{if(recovery!==null)download('discovery-recovery.json',recovery);};
try{let raw=sessionStorage.getItem(KEY);if(raw===null){try{raw=localStorage.getItem(KEY);}catch{}}if(raw){try{if(new TextEncoder().encode(raw).byteLength>MAX_BYTES)throw Error('Draft exceeds size limit.');const parsed=JSON.parse(raw);validatePath(parsed);path=parsed;$('goal').value=path.goal;advice();$('actor').value=path.createdBy;render();tell('Search notes restored in this tab. Export a file before closing the tab.');}catch{recovery=raw;$('recover').hidden=false;tell('Saved search notes could not be read safely. Its original bytes are preserved.');}}}catch{tell('Tab storage unavailable; use file exports to keep work.');}
